import React, { useEffect, useState } from 'react';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, MenuItem, Select, Table, TableBody, TableCell, TableHead, TableRow, TextField, Checkbox, Typography } from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import SaveIcon from '@mui/icons-material/Save';

const controlTypes = [
  { value: 'text', label: 'Text' },
  { value: 'number', label: 'Number' },
  { value: 'password', label: 'Password' },
  { value: 'email', label: 'Email' },
  { value: 'radio', label: 'Radio' },
  { value: 'checkbox', label: 'Checkbox' },
  { value: 'month', label: 'Month' }
];

const ManageDynamicForm = () => {
  const [savedForms, setSavedForms] = useState([]);
  const [selectedForm, setSelectedForm] = useState(null);
  const [formFields, setFormFields] = useState([]);
  const [openConfirm, setOpenConfirm] = useState(false);
  const [formDescription, setFormDescription] = useState('');

  // useEffect(() => {
  //   const storedForms = JSON.parse(localStorage.getItem('savedForms')) || [];
  //   setSavedForms(storedForms);
  // }, []);

  // useEffect(() => {
  //   fetch('http://localhost:5000/api/get-forms')
  //     .then(response => response.json())
  //     .then(data => {
  //       setSavedForms(data); // Assuming 'data' is an array of form objects with 'id'
  //     })
  //     .catch(error => console.error('Error fetching forms:', error));
  // }, []);

  useEffect(() => {
    fetch('http://localhost:5000/api/get-forms')
      .then(response => response.json())
      .then(data => {
        const processedForms = data.map(form => {
          try {
            const formData = JSON.parse(form.form_data);
            return {
              ...form,
              formName: formData.formName,
              formDescription: formData.formDescription,
              fields: formData.fields, // Assuming fields are also inside form_data
            };
          } catch (error) {
            console.error('Error parsing form_data:', error, form);
            return form; // Return the original form in case of parsing error
          }
        });
        setSavedForms(processedForms.filter(form => form.formName)); // Ensure formName exists for rendering
      })
      .catch(error => console.error('Error fetching forms:', error));
  }, []);

  // const handleFormSelect = (event) => {
  //   const form = savedForms.find(f => f.formName === event.target.value);
  //   setSelectedForm(form);
  //   setFormFields([...form.fields]);
  //   setFormDescription(form.formDescription);
  // };

  const handleFormSelect = (event) => {
    const form = savedForms.find(f => f.formName === event.target.value);
    setSelectedForm(form); // 'form' should now include the 'id'
    setFormFields([...form.fields]);
    setFormDescription(form.formDescription);
  };

  const handleFieldChange = (index, field, value) => {
    const updatedFields = [...formFields];
    updatedFields[index][field] = value;

    // If optionsCount changed, update options array
    if (field === 'optionsCount') {
      const count = parseInt(value) || 0;
      updatedFields[index].options = Array(count).fill('');
    }

    setFormFields(updatedFields);
  };

  const handleOptionChange = (fieldIndex, optionIndex, value) => {
    const updatedFields = [...formFields];
    updatedFields[fieldIndex].options[optionIndex] = value;
    setFormFields(updatedFields);
  };

  const handleDeleteField = (index) => {
    const updatedFields = [...formFields];
    updatedFields.splice(index, 1);
    setFormFields(updatedFields);
  };

  const handleMoveField = (index, direction) => {
    const updatedFields = [...formFields];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex >= 0 && targetIndex < updatedFields.length) {
      const temp = updatedFields[index];
      updatedFields[index] = updatedFields[targetIndex];
      updatedFields[targetIndex] = temp;
      setFormFields(updatedFields);
    }
  };

  // const handleSave = () => {
  //     const updatedForms = savedForms.map(form =>
  //         form.formName === selectedForm.formName
  //             ? { ...form, formDescription, fields: formFields }
  //             : form
  //     );
  //     localStorage.setItem('savedForms', JSON.stringify(updatedForms));
  //     setSavedForms(updatedForms);
  //     setOpenConfirm(false);
  //     alert('Form saved successfully!');
  // };

  const handleSave = async () => {
    if (!selectedForm?.id) {
      alert('Error: Form ID is missing.');
      setOpenConfirm(false);
      return;
    }

    const updatedFormData = {
      formName: selectedForm.formName, // You might not need this if only updating fields/description
      formDescription: formDescription,
      fields: formFields,
    };

    try {
      const response = await fetch(`http://localhost:5000/api/update/${selectedForm.id}`, {
        method: 'PUT', // Or PATCH
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(updatedFormData),
      });

      if (response.ok) {
        const data = await response.json();
        // Update the local state to reflect the changes
        const updatedForms = savedForms.map(form =>
          form.id === selectedForm.id ? { ...form, formDescription, fields: formFields } : form
        );
        setSavedForms(updatedForms);
        localStorage.setItem('savedForms', JSON.stringify(updatedForms)); // Optionally update localStorage
        setOpenConfirm(false);
        alert(data.message || 'Form updated successfully!');
      } else {
        const errorData = await response.json();
        alert(errorData.error || 'Failed to update form.');
      }
    } catch (error) {
      console.error('Error updating form:', error);
      alert('Failed to update form. Please check your network.');
    }
  };

  return (
    <Box p={3}>
      <Typography variant="h6" gutterBottom>Manage Dynamic Form</Typography>
      <Select
        displayEmpty
        value={selectedForm?.formName || ''}
        onChange={handleFormSelect}
        fullWidth
        size="small"
      >
        <MenuItem value="" disabled>Select a form</MenuItem>
        {savedForms.map((form, index) => (
          <MenuItem key={index} value={form.formName}>
            {form.formName}
          </MenuItem>
        ))}
      </Select>

      {selectedForm && (
        <Box mt={3}>
          <Table>
            <TableHead>
              {selectedForm && (
                <TableRow>
                  <TableCell colSpan={9}>
                    <Typography variant="h6">Form Name: {selectedForm.formName}</Typography>
                  </TableCell>
                </TableRow>
              )}
              {selectedForm && (
                <TableRow>
                  <TableCell colSpan={9}>
                    <TextField
                      label="Form Description"
                      fullWidth
                      value={formDescription}
                      onChange={(e) => setFormDescription(e.target.value)}
                    />
                  </TableCell>
                </TableRow>
              )}
              <TableRow>
                <TableCell>Label</TableCell>
                <TableCell>Control Type</TableCell>
                <TableCell>Required</TableCell>
                <TableCell>Placeholder</TableCell>
                <TableCell>Error Message</TableCell>
                <TableCell>Helper Text</TableCell>
                <TableCell>Min Length</TableCell>
                <TableCell>Max Length</TableCell>
                <TableCell>Validate Email</TableCell>
                <TableCell>Options</TableCell>
                <TableCell>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {formFields.map((field, index) => (
                <TableRow key={index}>
                  <TableCell>
                    <TextField
                      value={field.label}
                      onChange={(e) => handleFieldChange(index, 'label', e.target.value)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <Select
                      value={field.controlType}
                      onChange={(e) => handleFieldChange(index, 'controlType', e.target.value)}
                      size="small"
                    >
                      {controlTypes.map((type) => (
                        <MenuItem key={type.value} value={type.value}>
                          {type.label}
                        </MenuItem>
                      ))}
                    </Select>
                  </TableCell>
                  <TableCell>
                    <Checkbox
                      checked={field.required}
                      onChange={(e) => handleFieldChange(index, 'required', e.target.checked)}
                    />
                  </TableCell>
                  <TableCell>
                    <TextField
                      value={field.placeholder}
                      onChange={(e) => handleFieldChange(index, 'placeholder', e.target.value)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <TextField
                      value={field.errorMessage}
                      onChange={(e) => handleFieldChange(index, 'errorMessage', e.target.value)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <TextField
                      value={field.helperText || ''}
                      onChange={(e) => handleFieldChange(index, 'helperText', e.target.value)}
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    {['text', 'number', 'password', 'email'].includes(field.controlType) && (
                      <TextField
                        type="number"
                        value={field.minLength || ''}
                        onChange={(e) => handleFieldChange(index, 'minLength', e.target.value)}
                        size="small"
                      />
                    )}
                  </TableCell>
                  <TableCell>
                    {['text', 'number', 'password', 'email'].includes(field.controlType) && (
                      <TextField
                        type="number"
                        value={field.maxLength || ''}
                        onChange={(e) => handleFieldChange(index, 'maxLength', e.target.value)}
                        size="small"
                      />
                    )}
                  </TableCell>
                  <TableCell>
                    {field.controlType === 'email' && (
                      <Checkbox
                        checked={field.validateEmail || false}
                        onChange={(e) => handleFieldChange(index, 'validateEmail', e.target.checked)}
                      />
                    )}
                  </TableCell>
                  <TableCell>
                    {['radio', 'checkbox'].includes(field.controlType) && (
                      <Box>
                        <TextField
                          label="Options Count"
                          type="number"
                          value={field.optionsCount || ''}
                          onChange={(e) => handleFieldChange(index, 'optionsCount', e.target.value)}
                          size="small"
                        />
                        {field.options?.map((option, optIndex) => (
                          <TextField
                            key={optIndex}
                            value={option}
                            onChange={(e) => handleOptionChange(index, optIndex, e.target.value)}
                            placeholder={`Option ${optIndex + 1}`}
                            size="small"
                            style={{ marginTop: 4 }}
                          />
                        ))}
                      </Box>
                    )}
                  </TableCell>
                  <TableCell>
                    <IconButton onClick={() => handleMoveField(index, 'up')}>
                      <ArrowUpwardIcon />
                    </IconButton>
                    <IconButton onClick={() => handleMoveField(index, 'down')}>
                      <ArrowDownwardIcon />
                    </IconButton>
                    <IconButton color="error" onClick={() => handleDeleteField(index)}>
                      <DeleteIcon />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          <Button
            variant="contained"
            color="primary"
            startIcon={<SaveIcon />}
            onClick={() => setOpenConfirm(true)}
            style={{ marginTop: 16 }}
          >
            Save Form
          </Button>
        </Box>
      )}

      {/* Confirmation Dialog */}
      <Dialog open={openConfirm} onClose={() => setOpenConfirm(false)}>
        <DialogTitle>Confirm Save</DialogTitle>
        <DialogContent>
          Are you sure you want to save changes to this form?
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenConfirm(false)} color="secondary">Cancel</Button>
          <Button onClick={handleSave} color="primary">Yes, Save</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageDynamicForm;

